static hqqrpc_status chrome_net_dispatch(hqqrpc_call *c) {
    switch (c->op) {
    case 1: return op_chrome_engine_create(c);
    case 2: return op_chrome_engine_destroy(c);
    case 3: return op_chrome_request_start(c);
    case 4: return op_chrome_request_write(c);
    case 5: return op_chrome_request_wait(c);
    case 6: return op_chrome_request_read(c);
    case 7: return op_chrome_request_destroy(c);
    case 8: return op_chrome_net_error_name(c);
    case 9: return op_chrome_ws_start(c);
    case 10: return op_chrome_ws_wait(c);
    case 11: return op_chrome_ws_destroy(c);
    case 12: return op_chrome_ws_read(c);
    case 13: return op_chrome_ws_write(c);
    case 14: return op_chrome_wt_start(c);
    case 15: return op_chrome_wt_wait(c);
    case 16: return op_chrome_wt_destroy(c);
    case 17: return op_chrome_wt_event(c);
    case 18: return op_chrome_wt_open_stream(c);
    case 19: return op_chrome_wt_stream_write(c);
    case 20: return op_chrome_wt_stream_abort(c);
    case 21: return op_chrome_wt_stream_consume(c);
    case 22: return op_chrome_wt_send_datagram(c);
    case 23: return op_chrome_wt_max_datagram(c);
    case 24: return op_chrome_wt_close(c);
    default: return HQQRPC_E_UNKNOWN_OP; /* default deny (7.1) */
    }
}

